definition.css:
@import 'tailwindcss' prefix(tw);

@theme {
  --*: initial;
  --spacing: 0.25rem;
  --color-red-500: red;
  --color-white: #fff;

  /* Equivalent of blue-500/50 */
  --color-primary: color-mix(in oklab, oklch(62.3% 0.214 259.815) 50%, transparent);
}

