definition.css:
@import 'tailwindcss';

@utility pill {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  height: 2rem;
  padding: 0.25rem 0.75rem;
  margin: 0;
  border-radius: 9999px;
  font-size: 0.875rem;
  line-height: 1.25rem;
  font-weight: 500;
  color: white;
  background-color: black;
  white-space: nowrap;
  overflow: hidden;
  cursor: pointer;
}

