definition.css:
@tailwind utilities;
@theme {
  --foreground: unset;
  --default: unset;
}
@theme inline {
  --color-foreground: var(--foreground);
  --color-default-soft-hover: color-mix(in oklab, var(--default) 60%, transparent);
}
